begin;

-- Phase 8: notification delivery triggers and report query indexes.
-- Notifications are generated by trusted database triggers; clients cannot insert arbitrary notices.

create index if not exists notifications_user_created_idx
  on public.notifications(user_id, created_at desc);
create index if not exists notifications_user_unread_idx
  on public.notifications(user_id, created_at desc) where read_at is null;
create index if not exists attendance_work_date_idx
  on public.attendance_records(work_date);
create index if not exists leave_status_created_idx
  on public.leave_applications(status, created_at desc);
create index if not exists payroll_period_status_idx
  on public.payroll_records(payroll_period, status);
create index if not exists training_needs_status_idx
  on public.training_needs(status, created_at desc);
create index if not exists recruitment_status_date_idx
  on public.recruitment_applications(status, application_date desc);
create index if not exists job_vacancies_status_date_idx
  on public.job_vacancies(status, opening_date desc);

create or replace function public.notify_employee_hr_event(
  p_employee_id uuid,
  p_title text,
  p_message text
) returns void
language plpgsql
security definer
set search_path = public
as $$
declare v_user_id uuid;
begin
  select id into v_user_id from public.profiles where employee_id=p_employee_id and is_active=true limit 1;
  if v_user_id is not null then
    insert into public.notifications(user_id,title,message) values(v_user_id,p_title,p_message);
  end if;
end;
$$;

create or replace function public.notify_leave_decision()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if new.status is distinct from old.status and new.status <> 'Pending' then
    perform public.notify_employee_hr_event(new.employee_id,'Leave application update',
      'Your '||new.leave_type||' leave request for '||new.start_date||' to '||new.end_date||' is '||lower(new.status)||'.');
  end if;
  return new;
end; $$;

drop trigger if exists trg_notify_leave_decision on public.leave_applications;
create trigger trg_notify_leave_decision after update of status on public.leave_applications
for each row execute function public.notify_leave_decision();

create or replace function public.notify_training_request()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if new.status is distinct from old.status then
    perform public.notify_employee_hr_event(new.employee_id,'Training request update',
      'Your training request "'||new.title||'" is now '||lower(new.status)||'.');
  end if;
  return new;
end; $$;

drop trigger if exists trg_notify_training_request on public.training_needs;
create trigger trg_notify_training_request after update of status on public.training_needs
for each row execute function public.notify_training_request();

create or replace function public.notify_payroll_status()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if new.status is distinct from old.status and new.status in ('Approved','Paid') then
    perform public.notify_employee_hr_event(new.employee_id,'Payroll update',
      'Your payroll record for '||to_char(new.payroll_period,'YYYY-MM')||' is '||lower(new.status)||'.');
  end if;
  return new;
end; $$;

drop trigger if exists trg_notify_payroll_status on public.payroll_records;
create trigger trg_notify_payroll_status after update of status on public.payroll_records
for each row execute function public.notify_payroll_status();

create or replace function public.notify_appraisal_finalized()
returns trigger language plpgsql security definer set search_path=public as $$
declare v_period text;
begin
  if new.status is distinct from old.status and new.status in ('Finalized','Completed') then
    select name into v_period from public.appraisal_periods where id=new.period_id;
    perform public.notify_employee_hr_event(new.employee_id,'Performance appraisal finalized',
      'Your performance appraisal for '||coalesce(v_period,'the appraisal period')||' has been finalized.');
  end if;
  return new;
end; $$;

drop trigger if exists trg_notify_appraisal_finalized on public.performance_appraisals;
create trigger trg_notify_appraisal_finalized after update of status on public.performance_appraisals
for each row execute function public.notify_appraisal_finalized();

create or replace function public.notify_hr_new_application()
returns trigger language plpgsql security definer set search_path=public as $$
declare p record;
begin
  for p in select id from public.profiles where role in ('administrator','hr') and is_active=true loop
    insert into public.notifications(user_id,title,message)
    values(p.id,'New recruitment application','A new candidate application has been received for '||new.position||'.');
  end loop;
  return new;
end; $$;

drop trigger if exists trg_notify_hr_new_application on public.recruitment_applications;
create trigger trg_notify_hr_new_application after insert on public.recruitment_applications
for each row execute function public.notify_hr_new_application();

-- Existing RLS policies allow each user to read and mark their own notifications.
-- These SECURITY DEFINER trigger functions create notifications on behalf of the system.

revoke execute on function public.notify_employee_hr_event(uuid,text,text) from public, anon, authenticated;
revoke execute on function public.notify_leave_decision() from public, anon, authenticated;
revoke execute on function public.notify_training_request() from public, anon, authenticated;
revoke execute on function public.notify_payroll_status() from public, anon, authenticated;
revoke execute on function public.notify_appraisal_finalized() from public, anon, authenticated;
revoke execute on function public.notify_hr_new_application() from public, anon, authenticated;

commit;
